OVERRIDES = {'音乐': 'yin yue', '乐理': 'yue li', '管弦乐': 'guan xian yue',
             '打击乐': 'da ji yue', '弦乐': 'xian yue', '民族音乐': 'min zu yin yue',
             '爵士乐': 'jue shi yue', '重唱': 'chong chang', '调式': 'diao shi',
             '调性': 'diao xing', '大调': 'da diao', '小调': 'xiao diao',
             '室内乐': 'shi nei yue'}

def main():
    for tag, (title, words) in CATEGORIES.items():
        terms = list(dict.fromkeys(words.split()))
        rows = [f'# 开心输入法专业小词库：{title}\n# 项目原创整理；默认关闭，在设置页按需开启。\n']
        for term in terms:
            code = OVERRIDES.get(term) or ' '.join(lazy_pinyin(term, style=Style.NORMAL))
            assert len(code.split()) == len(term), (term, code)
            rows.append(f'{term}\t{code}\t6000\n')
        name = f'professional_{tag}.txt'
        for directory in ('data_sources/lexicon_fragments/zh-ext', 'lexicon/zh-ext'):
            (ROOT / directory / name).write_text(''.join(rows), encoding='utf-8')
        print(f'{title}: {len(terms)}')

if __name__ == '__main__':
    main()
